package e2e
import("encoding/json";"fmt";"net/http";"os";"testing";"time")
func TestMediaControlAfsBindingE2E(t *testing.T){a,ctrl:=os.Getenv("MEDIA_AUTH_ADDR"),os.Getenv("MEDIA_CONTROL_ADDR");if a==""||ctrl==""{t.Skip("MEDIA_AUTH_ADDR and MEDIA_CONTROL_ADDR are required")};c:=httpClient(t);login(t,c,a,envOr("MEDIA_AUTH_E2E_USER","smoke"),envOr("MEDIA_AUTH_E2E_PASS","smoke123"));s,b:=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/workspaces",map[string]string{"name":fmt.Sprintf("afs-%d",time.Now().UnixNano()),"agent_type":"codex"});if s!=http.StatusCreated{t.Fatalf("workspace: %d %s",s,b)};var w struct{ID string};json.Unmarshal(b,&w);s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/afs-bindings",map[string]string{"workspace_id":w.ID,"external_ref":"afs-ext-1","desired_state":"active"});if s!=http.StatusCreated{t.Fatalf("binding: %d %s",s,b)};var bind struct{ID string};json.Unmarshal(b,&bind);s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/afs-bindings/"+bind.ID+"/members",map[string]string{"subject_id":"user-2","subject_type":"user","external_member_ref":"ext-user-2"});if s!=http.StatusCreated{t.Fatalf("member: %d %s",s,b)};s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/afs-bindings/"+bind.ID+"/reconcile",map[string]string{"observed_state":"ready"});if s!=http.StatusOK||!jsonContains(b,`"observed_state":"ready"`){t.Fatalf("reconcile: %d %s",s,b)};s,b=doJSON(t,c,http.MethodGet,ctrl+"/api/v1/afs-bindings/"+bind.ID+"/members",nil);if s!=http.StatusOK||!jsonContains(b,`"status":"pending"`){t.Fatalf("members: %d %s",s,b)};s,b=doJSON(t,c,http.MethodPost,ctrl+"/api/v1/afs-bindings/"+bind.ID+"/members/user-2/remove",map[string]any{});if s!=http.StatusOK||!jsonContains(b,`"status":"removed"`){t.Fatalf("remove: %d %s",s,b)}}
